class ShippingCost(Protocol):
    def cost(self, order) -> Decimal: ...

class Checkout:
    def __init__(self, shipping: ShippingCost):
        self.shipping = shipping

class Order:
    def __init__(self):
        self._listeners: list[OrderListener] = []
    def subscribe(self, listener: OrderListener):
        self._listeners.append(listener)
    def _changed(self):
        for listener in self._listeners:
            listener.order_changed(self)

class StripeGateway(PaymentGateway):
    def __init__(self, client: stripe.Client):
        self.client = client
    def charge(self, amount):
        return self.client.payment_intents.create(amount=int(amount * 100))

class OrderFacade:
    def place(self, cart):
        order = self.orders.create(cart)
        self.payments.charge(order)
        self.mailer.confirm(order)
